import('./server.mjs').then(async ({listTools, callTool}) => {
  console.log('Tools:', JSON.stringify(await listTools(), null, 2));
  console.log('---');
  // Basic case
  let r = await callTool('catalog_search', {query: 'widget', limit: 2});
  console.log('widget limit=2:', r.content[0].text);
  // With offset
  r = await callTool('catalog_search', {query: 'widget', limit: 2, offset: 2});
  console.log('widget offset=2 limit=2:', r.content[0].text);
  // Case insensitive
  r = await callTool('catalog_search', {query: 'WIDGET'});
  console.log('WIDGET (uppercase):', r.content[0].text);
  // Last page (no more)
  r = await callTool('catalog_search', {query: 'widget', limit: 2, offset: 3});
  console.log('widget offset=3:', r.content[0].text);
  // Missing query
  try { await callTool('catalog_search', {}); } catch(e) { console.log('missing query:', e.message); }
  // Limit out of range
  try { await callTool('catalog_search', {query: 'x', limit: 10}); } catch(e) { console.log('limit=10:', e.message); }
  try { await callTool('catalog_search', {query: 'x', limit: 0}); } catch(e) { console.log('limit=0:', e.message); }
  // Extra arg
  try { await callTool('catalog_search', {query: 'x', foo: 1}); } catch(e) { console.log('extra arg:', e.message); }
  // Wrong type
  try { await callTool('catalog_search', {query: 123}); } catch(e) { console.log('query number:', e.message); }
  try { await callTool('catalog_search', {query: 'x', limit: 'two'}); } catch(e) { console.log('limit string:', e.message); }
  try { await callTool('catalog_search', {query: 'x', offset: 1.5}); } catch(e) { console.log('offset float:', e.message); }
  // Unknown tool
  try { await callTool('nope', {}); } catch(e) { console.log('unknown tool:', e.message); }
});
" 2>&1"}

